def _decode(x, coef):
    from scipy.optimize import least_squares
    (offset, gain) = (coef[:4], coef[4:8])
    (coupling, interaction, cubic) = coef[8:]
    i = np.arange(4)
    j = (i + 1) % 4

    def residual(z, row):
        nxt = z[j]
        return offset + gain * z + coupling * nxt + interaction * z * nxt + cubic * z ** 3 - row

    def jacobian(z, row):
        g = np.diag(gain + interaction * z[j] + 3 * cubic * z * z)
        g[i, j] = coupling + interaction * z
        return g
    z = []
    for row in x:
        result = least_squares(residual, (row - offset) / gain, jac=jacobian, args=(row,), gtol=1e-12, max_nfev=80)
        if np.linalg.norm(result.fun, np.inf) > 1e-08:
            other = least_squares(residual, np.zeros(4), jac=jacobian, args=(row,), gtol=1e-12, max_nfev=100)
            if np.linalg.norm(other.fun) < np.linalg.norm(result.fun):
                result = other
        z.append(result.x)
    return np.asarray(z).reshape(-1, 4)

